CREATE OR REPLACE FUNCTION public.broker_protect_recipient_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('anon','authenticated') OR coalesce(auth.role(),'') IN ('anon','authenticated') THEN IF TG_OP='INSERT' THEN IF NEW.recipient_verified_at IS NOT NULL OR NEW.recipient_verified_email IS NOT NULL THEN RAISE EXCEPTION 'Recipient verification requires trusted provider verification'; END IF; ELSE IF NEW.recipient_verified_at IS DISTINCT FROM OLD.recipient_verified_at OR NEW.recipient_verified_email IS DISTINCT FROM OLD.recipient_verified_email THEN RAISE EXCEPTION 'Recipient verification requires trusted provider verification'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER broker_recipient_verification_guard BEFORE INSERT OR UPDATE ON public.freight_carriers FOR EACH ROW EXECUTE FUNCTION public.broker_protect_recipient_verification();
CREATE OR REPLACE FUNCTION public.broker_outbox_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.packet IS DISTINCT FROM OLD.packet OR NEW.recipient_email IS DISTINCT FROM OLD.recipient_email OR NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.draft_id IS DISTINCT FROM OLD.draft_id OR NEW.carrier_id IS DISTINCT FROM OLD.carrier_id THEN RAISE EXCEPTION 'Approved packet identity is immutable'; END IF; END IF; IF NEW.recipient_email IS NULL OR NEW.recipient_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR NEW.recipient_email ~ '[\r\n]' THEN RAISE EXCEPTION 'Valid recipient required'; END IF; IF NOT EXISTS(SELECT 1 FROM public.broker_intake_drafts d WHERE d.id=NEW.draft_id AND d.company_id=NEW.company_id AND d.status='approved' AND d.approved_by=NEW.approved_by AND d.selected_carrier_id=NEW.carrier_id) THEN RAISE EXCEPTION 'Approved carrier assignment required before outbox'; END IF; RETURN NEW; END $$;
CREATE TRIGGER broker_outbox_approval_guard BEFORE INSERT OR UPDATE ON public.broker_delivery_outbox FOR EACH ROW EXECUTE FUNCTION public.broker_outbox_guard();